import policy


def upload(send):
    """Call send() until it returns True, retrying as the policy allows. Returns the number of attempts made."""
    attempts = 0
    while True:
        attempts += 1
        if send():
            return attempts
        if not policy.may_retry(attempts):
            return attempts
```

